"use client";

import { type CSSProperties, type HTMLAttributes, type KeyboardEvent, type ReactNode, useMemo, useState } from "react";
import { cx } from "../utils/cx";

export type BarDatum = { label: string; value: number };

export type BarChartProps = Omit<HTMLAttributes<HTMLElement>, "title"> & {
  data: BarDatum[];
  title: ReactNode;
  /** Shown in the header when no bar is active ("Last 30 days"). */
  caption?: ReactNode;
  /** Number formatting for values (serializable, so a server component can pass it). */
  format?: Intl.NumberFormatOptions;
  locale?: string;
  /** Chart height. Default 9rem. */
  height?: string;
  /** Shown instead of bars when every value is zero or there is no data. */
  empty?: ReactNode;
};

/**
 * The studio revenue chart: thin gray bars that grow in once; the bar under the pointer (or keyboard focus) turns
 * white and its value replaces the caption (announced politely). One tab stop; arrows move between bars.
 */
export function BarChart({
  data,
  title,
  caption,
  format,
  locale,
  height,
  empty = "No data for this period.",
  className,
  style,
  ...rest
}: BarChartProps) {
  const [active, setActive] = useState<number | null>(null);
  const [focusIndex, setFocusIndex] = useState(Math.max(0, data.length - 1));
  const fmt = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  const max = Math.max(1, ...data.map((d) => d.value));
  const shown = active === null ? null : data[active];
  const hasData = data.some((d) => d.value > 0);

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const n = data.length;
    const keys: Record<string, number> = {
      ArrowRight: focusIndex + 1,
      ArrowLeft: focusIndex - 1,
      Home: 0,
      End: n - 1,
    };
    if (!(e.key in keys)) return;
    e.preventDefault();
    const to = Math.max(0, Math.min(n - 1, keys[e.key] ?? 0));
    setFocusIndex(to);
    setActive(to);
    e.currentTarget.querySelectorAll<HTMLButtonElement>(".hm-bar")[to]?.focus();
  };

  return (
    <figure {...rest} className={cx("hm-bar-chart", className)} style={{ ...style, "--_h": height } as CSSProperties}>
      <figcaption className="hm-bar-chart-head">
        <span className="hm-bar-chart-title">{title}</span>
        <span className="hm-bar-chart-caption" aria-live="polite">
          {shown ? `${shown.label} · ${fmt.format(shown.value)}` : caption}
        </span>
      </figcaption>
      {hasData ? (
        <>
          <div className="hm-bars" role="group" onPointerLeave={() => setActive(null)} onKeyDown={onKey}>
            {data.map((d, i) => (
              <button
                key={d.label}
                type="button"
                className="hm-bar"
                tabIndex={i === focusIndex ? 0 : -1}
                data-on={active === i ? "" : undefined}
                style={{ "--h": `${Math.max(2, (d.value / max) * 100)}%`, "--hm-i": i } as CSSProperties}
                aria-label={`${d.label}: ${fmt.format(d.value)}`}
                onPointerEnter={() => setActive(i)}
                onFocus={() => {
                  setFocusIndex(i);
                  setActive(i);
                }}
                onBlur={() => setActive(null)}
              />
            ))}
          </div>
          <div className="hm-bar-axis" aria-hidden="true">
            <span>{data[0]?.label}</span>
            <span>{data[data.length - 1]?.label}</span>
          </div>
        </>
      ) : (
        <p className="hm-empty">{empty}</p>
      )}
    </figure>
  );
}
